mapper.select:
SELECT ANY_VALUE(p.id) AS id, c.sku_id AS skuId, ANY_VALUE(p.name) AS name, ANY_VALUE(s.picture) AS picture, c.count AS count, c.price AS price, ANY_VALUE(s.price) AS nowPrice, ANY_VALUE(s.inventory) AS stock, c.selected AS selected, GROUP_CONCAT(sv.name ORDER BY ssv.sort_order SEPARATOR ' ') AS attrsText, ANY_VALUE(CASE WHEN s.status = 1 AND p.status = 1 THEN 1 ELSE 0 END) AS isEffective FROM user_cart c LEFT JOIN product_sku s ON c.sku_id = s.id LEFT JOIN product p ON s.product_id = p.id LEFT JOIN sku_spec_value ssv ON c.sku_id = ssv.sku_id LEFT JOIN spec_value sv ON ssv.spec_value_id = sv.id WHERE c.user_id = #{userId}
AND c.selected = 1
GROUP BY c.id ORDER BY c.update_time DESC
